def native_determinant(matrix, router):
    """Clear row denominators before the small exact determinant."""
    (denominators, rows) = ([], [])
    for i in range(matrix.rows):
        if router.restore_row(matrix, i, rows, denominators):
            pass
        else:
            entries = [router.call(0, 'cancel', matrix[i, j]) for j in range(matrix.cols)]
            router.observe('entries', entries)
            denominator = router.call(2, 'lcm', [router.call(1, 'denom', e) for e in entries])
            router.observe('denominator', denominator)
            rows.append([router.call(3, 'cancel', e * denominator) for e in entries])
            router.observe('clearedRow', rows[-1])
            denominators.append(denominator)
            router.row_complete(i, rows[-1], denominators[-1])
    polynomial_matrix = router.call(4, 'ImmutableMatrix', rows)
    router.observe('polynomial_matrix', polynomial_matrix)
    if router.restore_tail(polynomial_matrix, denominators):
        return router.finish(router.saved_tail)
    else:
        determinant = router.call(5, 'det', polynomial_matrix, method='domain-ge')
        router.observe('determinant', determinant)
        rational = router.call(7, 'cancel', determinant / router.call(6, 'prod', denominators))
        router.observe('rational', rational)
        return router.finish((router.call(8, 'fraction', rational), polynomial_matrix, tuple(denominators)))
